import {checkedAt,sources,trophies,steps,stages,collectibles,categories,regions,superWinConditions,ngRules} from './data.js';
import {config,world,run,player,collectionState,collectionBucket,setCollection,stampActor,newWorld,newPlayer,addRun,runLabel,importData} from './model.js';
import {mapSvg,bindMap} from './map.js';
const sharedPath=import.meta.url.includes('/dist/')?'../../../shared/roadmap-store.js':'../../shared/roadmap-store.js';
const {createStore}=await import(new URL(sharedPath,import.meta.url));
const core=window.SideProjectSync,$=id=>document.getElementById(id);
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={overview:'庭院總覽',roadmap:'遊玩 Roadmap',collectibles:'收集清單',map:'庭院示意圖',trophies:'46 項獎盃',ngplus:'NG+ 驗收',world:'世界／成員',sources:'來源與查證'};
const warningLabels={critical:'🔴 不可逆／易錯過',branch:'🟠 分歧／備份',prep:'🟡 提前準備',recommended:'🔵 推薦體驗',later:'⚪ 可延後'}; // taste-skill-ignore — 使用者規格指定的五種文字與色點警示。
const verificationLabels={verified:'已查證',unverified:'待查證',conflicting:'來源有差異'};
const layerNames={all:'全部圖層',ground:'地表',underground:'地下',underwater:'水下',high:'高處'};
let progress,review,ngBackupStamp,refreshPending=false;
const filter={search:'',category:'all',region:'all',status:'all',verification:'all',required:'all',layer:'all',trophyCategory:'all',trophyStatus:'all',stage:'start'};
const mapState={selectedId:'',selectedPersonal:'',placing:false,x:500,y:325};
const store=createStore(config,core,()=>{if(!refreshPending){refreshPending=true;queueMicrotask(async()=>{refreshPending=false;try{progress=await store.get();render();}catch(e){message(e.message);}});}});
const date=value=>value?new Date(value).toLocaleString('zh-TW',{hour12:false}):'尚未記錄';
const links=urls=>`<div class="sources">${[...new Set(urls)].map(url=>`<a href="${escape(url)}" target="_blank" rel="noopener noreferrer">${escape(Object.values(sources).find(s=>s.url===url)?.label||'資料來源')} ↗</a>`).join('')}</div>`;
const view=()=>Object.hasOwn(names,new URL(location.href).searchParams.get('view'))?new URL(location.href).searchParams.get('view'):'overview';
const regionName=id=>regions.find(r=>r.id===id)?.name||'區域待查證';
const options=(rows,current)=>rows.map(([value,label])=>`<option value="${escape(value)}" ${value===current?'selected':''}>${escape(label)}</option>`).join('');
const filterSelect=(id,label,rows,key)=>`<label>${label}<select id="${id}" data-filter="${key}">${options(rows,filter[key])}</select></label>`;
const stateOptions=current=>options([['missing','未取得'],['obtained','已取得'],['unknown','待確認']],current);
function message(text){$('feedback').textContent=text;}
async function action(fn){try{await fn();}catch(e){message(e.message);}}
async function update(fn){const w=world(progress),scope=[w.worldId,w.currentRunId,w.currentPlayerId];await store.update(p=>{const w=world(p);if(w.worldId!==scope[0]||w.currentRunId!==scope[1]||w.currentPlayerId!==scope[2])throw Error('其他分頁已切換世界、周目或成員，請重新操作。');fn(p);return p;});}
function go(next,extra={}){const url=new URL(location.href);url.searchParams.set('view',next);for(const [key,value]of Object.entries(extra))url.searchParams.set(key,value);url.hash='';history.pushState({},'',url);render();window.scrollTo(0,0);$('app').focus({preventScroll:true});}
function header(){const w=world(progress),r=run(progress),pl=player(progress),earned=trophies.filter(t=>pl.trophies[t.id]?.earned).length,done=superWinConditions.filter(c=>r.conditions[c.id]?.done).length;return `<div class="page-heading"><div><h1>${names[view()]}</h1><p class="scope">${escape(w.name)} · ${runLabel(r)} · ${escape(pl.name)} · 本機手動記錄</p></div><small>最後更新 ${date(progress.updatedAt)}</small></div><div class="stats"><div><small>個人 PlayStation 獎盃</small><strong id="trophy-count">${earned} / 46</strong></div><div><small>本周目 Roadmap</small><strong>${steps.filter(s=>r.steps[s.id]?.done).length} / ${steps.length}</strong></div><div><small>Super Win 人工核對</small><strong>${done} / ${superWinConditions.length}</strong></div><div><small>目前故事階段</small><strong style="font-size:17px">${escape(stages.find(s=>s.id===run(progress).storyStage)?.title||stages[0].title)}</strong></div></div>`;}
function overviewHtml(){const r=run(progress),stage=run(progress).storyStage||'start',pending=steps.filter(s=>!r.steps[s.id]?.done&&(progress.settings.goal!=='platinum'||s.platinum)),next=pending.find(s=>stages.findIndex(t=>t.id===s.stageId)>=stages.findIndex(t=>t.id===stage))||pending[0];return `<div class="overview-grid"><section class="panel"><h2>下一個主線目標</h2>${next?`<p class="next">${escape(next.title)}</p><p>${escape(next.action)}</p><button class="primary" data-step-link="${next.id}">前往這一步</button>`:'<p>Roadmap 已核對完畢；請以遊戲內紀錄確認結局與獎盃。</p>'}<div class="warning"><strong>REMIX.R 前先查漏</strong><p>建議在第一輪先取得 Super Win。進 NG+ 後普通乳牙改為隨機位置，故事重新開始。</p></div><div class="toolbar">${filterSelect('overview-stage','目前故事階段',stages.map(s=>[s.id,s.title]),'stage')}</div></section><section class="panel"><h2>共同遊玩規則</h2><p>主線與收集依世界／周目記錄；獎盃依目前成員分開。完成者可追溯，重新取消可修正誤勾。</p><p>本頁不連接遊戲 Shared World，也不會即時同步給朋友。</p><button data-go="world">管理世界與成員</button><hr><h2>今日建議</h2><p>遇到收集品先記錄；未知位置可加個人標記。金卡不是 Super Win 必要條件。</p><button data-go="map">查看庭院示意圖</button></section></div><section><h2>收集概況</h2><p class="muted">只計本站已收錄項目；資料庫未齊，不顯示完整收集率。</p>${categorySummary()}</section>`;}
function categorySummary(){return `<div class="category-grid">${categories.map(c=>{const rows=collectibles.filter(i=>i.category===c.id),done=rows.filter(i=>collectionState(progress,i)==='obtained').length;return `<div class="list-summary"><div><a href="?view=collectibles" data-category-link="${c.id}">${escape(c.name)}</a><small style="display:block">資料庫未齊${c.referenceTotal?' · 第一輪來源參考 '+c.referenceTotal+' 項':''}</small></div><strong>${done} / ${rows.length} 已收錄</strong></div>`;}).join('')}</div>`;}
function roadmapHtml(){const stage=stages.some(s=>s.id===filter.stage)?filter.stage:'start',r=run(progress),rows=steps.filter(s=>s.stageId===stage).filter(s=>progress.settings.goal!=='platinum'||s.platinum).filter(s=>(s.title+s.action+(r.steps[s.id]?.note||'')).toLowerCase().includes(filter.search.toLowerCase()));return `<div class="toolbar">${filterSelect('stage-select','瀏覽章節',stages.map(s=>[s.id,s.number+' '+s.title]),'stage')}<label>遊玩目標<select id="goal">${options([['experience','完整體驗'],['platinum','白金目標']],progress.settings.goal)}</select></label><label class="search">搜尋步驟<input id="search" data-filter="search" value="${escape(filter.search)}" type="search"></label></div><p class="muted">這是建議順序。Hedge、Pond、Haze、Black Anthill 可依裝備平行探索；前置是準備提示，不鎖定瀏覽或代填完成。白金目標仍包含 NG+ 兩盃。</p>${rows.map(s=>{const done=r.steps[s.id]?.done;return `<article class="row ${done?'done':''}" id="step-${s.id}"><div class="row-heading"><h3><label class="check-label"><input id="step-check-${s.id}" type="checkbox" data-step="${s.id}" ${done?'checked':''}>${escape(s.title)}</label></h3><small>${done?'完成':'未開始'}</small></div><div class="metadata"><span>${regionName(s.regionId)}</span><span>${warningLabels[s.warning]}</span><span>${verificationLabels[s.verification]}</span></div>${done?'':`<p>${escape(s.action)}</p>`}<details id="detail-step-${s.id}"><summary>${s.spoiler?'展開攻略、劇透與筆記':'展開準備、關聯與筆記'}</summary>${done?`<p>${escape(s.action)}</p>`:''}<p>前置參考：${s.prerequisites.length?s.prerequisites.map(id=>escape(steps.find(t=>t.id===id)?.title||id)).join('、'):'無固定前置'}</p><p>準備：${escape(s.gear)}</p><p class="muted">耗時：${escape(s.duration)}</p><div class="actions">${s.trophyIds.map(id=>`<button data-trophy-link="${id}">${escape(trophies.find(t=>t.id===id).officialName)}</button>`).join('')}${s.collectibleIds.map(id=>`<button data-collection-link="${id}">收集：${escape(collectibles.find(i=>i.id===id)?.officialName||id)}</button>`).join('')}</div><label>自訂備註<textarea id="step-note-${s.id}" data-step-note="${s.id}" maxlength="5000">${escape(r.steps[s.id]?.note||'')}</textarea></label><small>完成時間：${date(r.steps[s.id]?.completedAt)} · 記錄者：${escape(world(progress).players[r.steps[s.id]?.completedBy]?.name||'未記錄')}</small>${links(s.sourceUrls)}</details></article>`;}).join('')||'<p class="empty">沒有符合條件的步驟。</p>'}`;}
function collectionFilters(){return `<div class="toolbar"><label class="search">名稱／位置搜尋<input id="collection-search" type="search" data-filter="search" value="${escape(filter.search)}"></label>${filterSelect('category-filter','分類',[['all','全部分類'],...categories.map(c=>[c.id,c.name])],'category')}${filterSelect('region-filter','區域',[['all','全部區域'],...regions.map(r=>[r.id,r.name])],'region')}${filterSelect('status-filter','狀態',[['all','全部狀態'],['missing','未取得'],['obtained','已取得'],['unknown','待確認']],'status')}${filterSelect('verification-filter','查證',[['all','全部查證'],...Object.entries(verificationLabels)],'verification')}${filterSelect('required-filter','用途',[['all','所有用途'],['platinum','白金相關（含 Super Win）'],['super-win','Super Win']],'required')}${view()==='map'?filterSelect('layer-filter','圖層',Object.entries(layerNames),'layer'):''}</div>`;}
function filteredItems(){return collectibles.filter(i=>run(progress).level===0||i.category!=='milk').filter(i=>filter.category==='all'||i.category===filter.category).filter(i=>filter.region==='all'||i.regionId===filter.region).filter(i=>filter.status==='all'||collectionState(progress,i)===filter.status).filter(i=>filter.verification==='all'||i.verification===filter.verification).filter(i=>filter.required==='all'||(filter.required==='super-win'?i.requiredFor.includes('super-win'):i.requiredFor.length>0)).filter(i=>view()!=='map'||filter.layer==='all'||i.layer===filter.layer).filter(i=>(i.officialName+i.locationDescription+regionName(i.regionId)).toLowerCase().includes(filter.search.toLowerCase()));}
function collectionRow(i,map=false){const status=collectionState(progress,i),row=collectionBucket(progress,i)[i.id];return `<article class="row ${status==='obtained'?'done':''} ${mapState.selectedId===i.id?'selected-item':''}" id="collect-${i.id}"><div class="row-heading"><h3>${escape(i.officialName)}</h3><label><span class="muted">取得狀態 </span><select id="collect-state-${i.id}" class="status-picker" data-collect="${i.id}" aria-label="${escape(i.officialName)} 狀態">${stateOptions(status)}</select></label></div><div class="metadata"><span>${categories.find(c=>c.id===i.category).name}</span><span>${regionName(i.regionId)} · ${layerNames[i.layer]}</span><span>${verificationLabels[i.verification]}</span><span>${i.requiredFor.length?'白金相關':'必要性待查證'}</span></div><p>${escape(i.locationDescription)}</p><small>區域已知，精確位置待查證 · ${i.worldScope==='base'?'第一輪位置':'跨周目內容'} · ${i.spawnRule==='fixed'?'固定位置':'出現規則待查證'}</small><div class="actions"><button data-locate="${i.id}">${map?'聚焦此區域':'在示意圖定位'}</button>${map?`<button data-collection-link="${i.id}">前往收集清單</button>`:''}</div><details id="detail-collect-${i.id}"><summary>備註與來源</summary><label>自訂備註<textarea id="collection-note-${i.id}" data-collection-note="${i.id}" maxlength="5000">${escape(row?.note||'')}</textarea></label><small>最後記錄：${date(row?.updatedAt)} · ${escape(world(progress).players[row?.completedBy]?.name||'未記錄')}</small>${links(i.sourceUrls)}</details></article>`;}
function matrixHtml(){const r=run(progress);return `<section class="panel"><h2>Super Win 條件核對</h2><p>以下是社群條件矩陣，不是遊戲評分百分比。每一項都需回到遊戲核對；收集清單完成不會自動勾選條件或獎盃。</p><p><strong>官方已確認：Gold Cards 不必要。</strong>第一輪優先完成 100%，再考慮 REMIX.R。</p><div class="matrix">${superWinConditions.map(c=>`<div class="row"><label class="check-label"><input id="condition-${c.id}" data-condition="${c.id}" type="checkbox" ${r.conditions[c.id]?.done?'checked':''}><span><strong>${c.title}</strong><small style="display:block">${escape(c.detail)}</small></span></label></div>`).join('')}</div>${links([sources.report.url,sources.official.url])}</section>`;}
function collectionsHtml(){const rows=filteredItems();return `<p class="warning">本站收錄 ${collectibles.length} 個具名項目，逐項資料庫未齊；參考總數不代表已列出全部項目。${run(progress).level?'NG+ 普通乳牙改用獨立記錄，第一輪位置不混入本周目。':''}</p>${categorySummary()}${collectionFilters()}<p class="muted">符合 ${rows.length} 項。取得狀態可撤回；獎盃需獨立確認。</p>${rows.map(i=>collectionRow(i)).join('')||'<p class="empty">沒有符合條件的已收錄項目。未收錄內容可先以個人標記與世界筆記保存。</p>'}${matrixHtml()}`;}
function trophyHtml(){const pl=player(progress),rows=trophies.filter(t=>filter.trophyCategory==='all'||t.category===filter.trophyCategory).filter(t=>filter.trophyStatus==='all'||!!pl.trophies[t.id]?.earned===(filter.trophyStatus==='earned')).filter(t=>(t.officialName+t.condition).toLowerCase().includes(filter.search.toLowerCase()));return `<p>依 ${escape(pl.name)} 的 PlayStation 實際跳盃勾選；主線、收集和其他玩家的勾選均不會代填。46 項包含 REMIX.R 與 NG+ 結局，沒有 DLC 額外清單。</p><div class="toolbar"><label class="search">搜尋名稱／條件<input id="trophy-search" type="search" data-filter="search" value="${escape(filter.search)}"></label>${filterSelect('trophy-status','取得狀態',[['all','全部'],['earned','已取得'],['pending','未取得']],'trophyStatus')}${filterSelect('trophy-category','分類',[['all','全部分類'],['story','故事'],['combat','戰鬥'],['craft','製作／基地'],['explore','探索'],['collection','收集'],['ngplus','NG+'],['meta','白金']],'trophyCategory')}</div>${rows.map(t=>{const associated=steps.filter(s=>s.trophyIds.includes(t.id));return `<article id="trophy-${t.id}" class="row"><div class="row-heading"><h3><label class="check-label"><input id="trophy-check-${t.id}" data-trophy="${t.id}" type="checkbox" ${pl.trophies[t.id]?.earned?'checked':''}>${escape(t.officialName)}</label></h3><small>${{platinum:'白金',gold:'金',silver:'銀',bronze:'銅'}[t.grade]} · ${verificationLabels[t.verification]}</small></div><p>${escape(t.condition)}</p><details id="detail-trophy-${t.id}"><summary>關聯 Roadmap／收集與可補救性</summary><div class="actions">${associated.map(s=>`<button data-step-link="${s.id}">${escape(s.title)}</button>`).join('')}${collectibles.some(i=>i.requiredFor.includes(t.id))?`<button data-trophy-collection="${t.id}">查看相關收集</button>`:''}</div><p class="muted">${escape(t.remedy)}</p>${links(t.sourceUrls)}</details></article>`;}).join('')||'<p class="empty">沒有符合的獎盃。</p>'}`;}
function mapHtml(){const rows=filteredItems(),r=run(progress),groups=regions.map(reg=>{const items=rows.filter(i=>i.regionId===reg.id);return {id:reg.id,count:items.length,done:items.filter(i=>collectionState(progress,i)==='obtained').length};}),personal=Object.fromEntries(Object.entries(r.customMarkers).filter(([,m])=>filter.layer==='all'||m.layer===filter.layer));return `<p>原創概念區域圖，非等比例、非導航地圖。所有收集品只聚合到區域，<strong>目前沒有已核實的精確點位</strong>。點區域可篩選清單，清單也可反向定位。</p>${collectionFilters()}<div class="map-layout"><div class="map-frame"><div class="map-controls"><button data-map-control="in" aria-label="放大">＋</button><button data-map-control="out" aria-label="縮小">−</button><button data-map-control="left" aria-label="向左平移">←</button><button data-map-control="up" aria-label="向上平移">↑</button><button data-map-control="down" aria-label="向下平移">↓</button><button data-map-control="right" aria-label="向右平移">→</button><button data-map-control="reset">全圖</button><button id="clear-map-filter">全部區域</button></div><div class="map-viewport">${mapSvg(groups,personal,filter.region,escape)}</div><p class="map-caption">矩形：示意區域群組 · 三角形：個人標記。可拖曳空白處；方向鍵平移、＋／− 縮放、Home 還原。</p></div><section class="map-list" aria-label="地圖篩選結果"><h2>${rows.length} 個符合項目</h2>${rows.map(i=>collectionRow(i,true)).join('')||'<p class="empty">這個圖層／篩選尚無已收錄項目。可先新增個人標記。</p>'}</section></div><section class="panel"><h2>個人標記</h2><p>個人位置由你指定，僅用於本周目筆記；不混入查證收集品或完成率。</p><form id="marker-form"><div class="form-grid"><label>名稱<input id="marker-name" required maxlength="100"></label><label>圖層<select id="marker-layer">${options(Object.entries(layerNames).filter(([id])=>id!=='all'),filter.layer==='all'?'ground':filter.layer)}</select></label><label>示意圖 X（0–1000）<input id="marker-x" type="number" min="0" max="1000" value="${mapState.x}" required></label><label>示意圖 Y（0–650）<input id="marker-y" type="number" min="0" max="650" value="${mapState.y}" required></label><label class="full">備註<textarea id="marker-note" maxlength="5000"></textarea></label></div><div class="actions spacer"><button id="place-marker" type="button" aria-pressed="${mapState.placing}">${mapState.placing?'點圖選位置中；再次按此取消':'在示意圖選個人位置'}</button><button type="submit">保存個人標記</button></div></form>${Object.entries(r.customMarkers).map(([id,m])=>`<article class="row ${mapState.selectedPersonal===id?'selected-item':''}" id="personal-${id}"><label class="check-label"><input type="checkbox" id="marker-check-${id}" data-marker-done="${id}" ${m.done?'checked':''}><strong>${escape(m.name)}</strong></label><p>${escape(m.note)}</p><small>${escape(layerNames[m.layer]||m.layer)} · 個人示意位置 (${m.x}, ${m.y})</small></article>`).join('')||'<p class="muted">尚無個人標記。</p>'}</section>`;}
function ngHtml(){const w=world(progress),r=run(progress);return `<div class="toolbar"><label>瀏覽周目<select id="run-select">${options(Object.entries(w.runs).map(([id,r])=>[id,runLabel(r)]),w.currentRunId)}</select></label></div><section class="panel"><h2>REMIX.R 前驗收</h2><p>這裡只建立網站清單，不操作遊戲存檔。舊周目完整保留，可隨時切回查看。</p>${['broodmother','mantis','wasp-queen','javamatic'].map(id=>`<p>${r.steps[id]?.done?'已記錄':'未記錄'} · ${escape(steps.find(s=>s.id===id).title)}</p>`).join('')}<div class="warning">先在遊戲保留可辨識的存檔。確認第一輪 Super Win 後再啟動 REMIX.R，能減少新周目的收集負擔。</div><button id="ng-backup">下載網站周目切換前備份</button><label class="check-label"><input id="ng-ack" type="checkbox">我已保存下載檔，並已在遊戲啟動 REMIX.R，現在要建立下一周目清單</label><button id="ng-create" disabled>建立下一個 NG+ 清單</button></section><section><h2>繼承／重置規則</h2>${ngRules.map(rule=>`<article class="row"><h3>${rule.title}</h3><p>${rule.detail}</p>${links([sources[rule.source].url])}</article>`).join('')}</section><section class="panel"><h2>本周目隨機乳牙記錄</h2><p>社群資料為每輪 66 顆、從 219 個候選位置中選出；候選不是必收數量。本站沒有未核實候選座標，此計數是你回到遊戲核對後的獨立記錄。</p>${r.level?`<div class="form-grid"><label>已核對取得數<input id="ng-molar-count" type="number" min="0" max="999" step="1" value="${r.ngMolars.count}"></label><label>核對狀態<select id="ng-molar-status">${stateOptions(r.ngMolars.status)}</select></label></div>`:'<p>目前是第一輪；普通乳牙請在收集清單逐項追蹤。進入 NG+ 後才啟用此獨立計數。</p>'}${links([sources.ng.url])}</section>`;}
function worldHtml(){const w=world(progress),pl=player(progress);return `<div class="toolbar"><label>世界<select id="world-select">${options(Object.values(progress.worlds).map(w=>[w.worldId,w.name]),w.worldId)}</select></label><label>目前成員<select id="player-select">${options(Object.values(w.players).map(p=>[p.playerId,p.name]),w.currentPlayerId)}</select></label><label>周目<select id="run-select">${options(Object.entries(w.runs).map(([id,r])=>[id,runLabel(r)]),w.currentRunId)}</select></label></div><p class="warning">本機成員標籤及 JSON 交換，不是即時多人同步。遊戲 Shared World 的雲端服務由遊戲管理；這裡不能讀取主機或 PSN。</p><section class="panel"><h2>世界共同紀錄</h2><div class="form-grid"><label>世界名稱<input id="world-name" maxlength="100" value="${escape(w.name)}"></label><label>世界 ID<input readonly value="${escape(w.worldId)}" aria-label="世界 ID"></label><label class="full">世界共同筆記<textarea id="world-notes" maxlength="10000">${escape(w.notes||'')}</textarea></label></div><p class="muted">主線、條件矩陣與位置收集依周目分開；SCA.B／巨型乳牙等明確繼承類別在本世界共用。</p></section><section class="panel"><h2>個人紀錄 · ${escape(pl.name)}</h2><div class="form-grid"><label>成員名稱<input id="player-name" maxlength="100" value="${escape(pl.name)}"></label><label>玩家 ID<input readonly value="${escape(pl.playerId)}" aria-label="玩家 ID"></label><label class="full">個人強化／備註<textarea id="player-notes" maxlength="10000">${escape(pl.notes||'')}</textarea></label></div><p class="muted">PSN 獎盃與個人強化筆記依成員分開，不從世界收集自動推算角色數值。</p></section><section class="panel"><h2>新增世界／成員</h2><form id="add-world-form"><label>新世界名稱<input id="new-world-name" required maxlength="100"></label><button class="spacer">新增獨立世界</button></form><form id="add-player-form"><label>新成員名稱<input id="new-player-name" required maxlength="100"></label><button class="spacer">新增本機成員</button></form></section>${links([sources.shared.url,sources.crossplay.url])}`;}
function sourcesHtml(){return `<section class="definition"><h2>資料基準 · ${checkedAt}</h2><p>Grounded 本體，非 Grounded 2。依公開 PS4／PS5 46 項清單建立，繁中條件是本站摘要。本站 ID 不是官方 PSN 數字 ID。</p><p>最新可查官方修補紀錄：1.4.7.4815（2025-05-12）。PS4／PS5 實際安裝版本仍需主機確認。</p><p>來源直接存取部分回傳 403，使用搜尋索引回傳文字核對，未繞過驗證。維基有混合兩代條目，僅納入 Grounded 段落；圖像、底圖、座標與圖磚皆未使用。</p><p>收集品 ${collectibles.length} 項；所有分類均未宣稱完整。沒有用 78／45／51 的參考總數產生空白假項目。特殊配方、生物卡目前僅收錄已查證子集；其餘逐項資料仍待補齊。</p><p>Underexposed 的來源分別寫進入照片模式／拍照，已標來源差異。錄音逐項歸類與位置尚待核實，不連結為白金必要。獎盃可補救與多人補跳機制未實機驗收。</p><p>Super Win 條件矩陣來自社群資料，沒有宣稱能計算遊戲評分。官方 1.4 已確認 Gold Cards 不必要。</p><p>本機使用 Grounded 獨立 IndexedDB；網站完整備份保存未知資料、快照及匯入兩端原文。沒有 SW、背景同步或 Google Drive 寫入。跨分頁讀取最新值後再交易；匯入預覽過期即停止。</p></section><section>${Object.values(sources).map(s=>`<article class="row"><h3>${escape(s.label)}</h3><a href="${escape(s.url)}" target="_blank" rel="noopener noreferrer">開啟來源 ↗</a></article>`).join('')}</section>`;}
function render(){if(!progress)return;const active=document.activeElement,focusId=active?.id,draft=active?.matches('textarea,input[type=text],input:not([type])')?active.value:undefined,selection=typeof active?.selectionStart==='number'?[active.selectionStart,active.selectionEnd]:null,open=[...$('app').querySelectorAll('details[open]')].map(d=>d.id);$('app').innerHTML=header()+({overview:overviewHtml,roadmap:roadmapHtml,collectibles:collectionsHtml,map:mapHtml,trophies:trophyHtml,ngplus:ngHtml,world:worldHtml,sources:sourcesHtml}[view()]())+`<p class="footer">查證 ${checkedAt} · 網站備份不包含遊戲存檔 · 資料庫尚未齊全</p>`;for(const id of open)if($(id))$(id).open=true;document.querySelectorAll('[data-view]').forEach(a=>{if(a.dataset.view===view())a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(focusId&&$(focusId)){if(draft!==undefined)$(focusId).value=draft;$(focusId).focus({preventScroll:true});if(selection&&$(focusId).setSelectionRange)try{$(focusId).setSelectionRange(...selection);}catch{}}bindControls();if(view()==='map')bindMap({selectRegion:id=>{filter.region=id;render();},selectPersonal:id=>{mapState.selectedPersonal=id;render();$('personal-'+id)?.scrollIntoView({block:'center'});},getPlacing:()=>mapState.placing,place:(x,y)=>{mapState.x=x;mapState.y=y;mapState.placing=false;$('marker-x').value=x;$('marker-y').value=y;$('place-marker').textContent='在示意圖選個人位置';$('place-marker').setAttribute('aria-pressed','false');$('marker-name').focus();}});}
function focusItem(id){requestAnimationFrame(()=>{$(id)?.scrollIntoView({block:'center'});const focus=$(id)?.querySelector('input,select,button');focus?.focus({preventScroll:true});});}
function bindControls(){
 document.querySelectorAll('[data-filter]').forEach(input=>input.addEventListener(input.tagName==='INPUT'?'input':'change',()=>{filter[input.dataset.filter]=input.value;if(input.id==='stage-select'){const url=new URL(location.href);url.searchParams.set('stage',input.value);history.replaceState({},'',url);}render();}));
 document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));
 document.querySelectorAll('[data-step-link]').forEach(b=>b.onclick=()=>{const s=steps.find(s=>s.id===b.dataset.stepLink);filter.stage=s.stageId;filter.search='';go('roadmap',{stage:s.stageId});focusItem('step-'+s.id);});
 document.querySelectorAll('[data-trophy-link]').forEach(b=>b.onclick=()=>{filter.search='';filter.trophyCategory='all';filter.trophyStatus='all';go('trophies');focusItem('trophy-'+b.dataset.trophyLink);});
 document.querySelectorAll('[data-category-link]').forEach(b=>b.onclick=e=>{e.preventDefault();resetCollectionFilters();filter.category=b.dataset.categoryLink;go('collectibles');});
 document.querySelectorAll('[data-collection-link]').forEach(b=>b.onclick=()=>{resetCollectionFilters();go('collectibles');focusItem('collect-'+b.dataset.collectionLink);});
 document.querySelectorAll('[data-locate]').forEach(b=>b.onclick=()=>{const i=collectibles.find(i=>i.id===b.dataset.locate);resetCollectionFilters();filter.region=i.regionId;filter.layer=i.layer;mapState.selectedId=i.id;go('map');focusItem('collect-'+i.id);});
 document.querySelectorAll('[data-trophy-collection]').forEach(b=>b.onclick=()=>{resetCollectionFilters();const items=collectibles.filter(i=>i.requiredFor.includes(b.dataset.trophyCollection));if(b.dataset.trophyCollection==='flavorful')filter.category='scab';if(b.dataset.trophyCollection==='mini-mix-a-lot')filter.category='mix';go('collectibles');if(items[0])focusItem('collect-'+items[0].id);});
 document.querySelectorAll('[data-step]').forEach(input=>input.onchange=()=>{const done=input.checked,id=input.dataset.step;void action(()=>update(p=>{const rows=run(p).steps;rows[id]={...rows[id],done,completedAt:done?Date.now():null,...stampActor(p)};}));});
 document.querySelectorAll('[data-step-note]').forEach(input=>input.onchange=()=>{const note=input.value,id=input.dataset.stepNote;void action(()=>update(p=>{const rows=run(p).steps;rows[id]={done:false,...rows[id],note,...stampActor(p)};}));});
 document.querySelectorAll('[data-trophy]').forEach(input=>input.onchange=()=>{const earned=input.checked,id=input.dataset.trophy;void action(()=>update(p=>{const rows=player(p).trophies;rows[id]={...rows[id],earned,...stampActor(p)};}));});
 document.querySelectorAll('[data-collect]').forEach(input=>input.onchange=()=>{const status=input.value,item=collectibles.find(i=>i.id===input.dataset.collect);void action(()=>update(p=>setCollection(p,item,status)));});
 document.querySelectorAll('[data-collection-note]').forEach(input=>input.onchange=()=>{const note=input.value,item=collectibles.find(i=>i.id===input.dataset.collectionNote);void action(()=>update(p=>{const rows=collectionBucket(p,item);rows[item.id]={status:'missing',...rows[item.id],note,...stampActor(p)};}));});
 document.querySelectorAll('[data-condition]').forEach(input=>input.onchange=()=>{const done=input.checked,id=input.dataset.condition;void action(()=>update(p=>{const rows=run(p).conditions;rows[id]={...rows[id],done,...stampActor(p)};}));});
 document.querySelectorAll('[data-marker-done]').forEach(input=>input.onchange=()=>{const done=input.checked,id=input.dataset.markerDone;void action(()=>update(p=>{Object.assign(run(p).customMarkers[id],{done,...stampActor(p)});}));});
 if($('overview-stage')){$('overview-stage').value=run(progress).storyStage||'start';$('overview-stage').onchange=event=>{const value=event.target.value;void action(()=>update(p=>{run(p).storyStage=value;}));};}
 if($('goal'))$('goal').onchange=e=>{const goal=e.target.value;void action(()=>update(p=>{p.settings.goal=goal;}));};
 for(const [id,fn]of [['world-name',(p,v)=>world(p).name=v],['world-notes',(p,v)=>world(p).notes=v],['player-name',(p,v)=>player(p).name=v],['player-notes',(p,v)=>player(p).notes=v]])if($(id))$(id).onchange=e=>{const value=e.target.value.trim();if(id.endsWith('name')&&!value){render();return;}void action(()=>update(p=>fn(p,value)));};
 if($('world-select'))$('world-select').onchange=e=>{const id=e.target.value;void action(()=>store.update(p=>{if(!Object.hasOwn(p.worlds,id))throw Error('找不到世界');p.currentWorldId=id;return p;}));};
 for(const [id,key,group]of [['run-select','currentRunId','runs'],['player-select','currentPlayerId','players']])if($(id))$(id).onchange=e=>{const value=e.target.value;void action(()=>update(p=>{const w=world(p);if(!Object.hasOwn(w[group],value))throw Error('找不到記錄');w[key]=value;}));};
 if($('add-world-form'))$('add-world-form').onsubmit=e=>{e.preventDefault();const name=$('new-world-name').value.trim();if(!name)return;void action(()=>store.update(p=>{const w=newWorld(name);p.worlds[w.worldId]=w;p.currentWorldId=w.worldId;return p;}));};
 if($('add-player-form'))$('add-player-form').onsubmit=e=>{e.preventDefault();const name=$('new-player-name').value.trim();if(!name)return;void action(()=>update(p=>{const w=world(p),pl=newPlayer(name);w.players[pl.playerId]=pl;w.currentPlayerId=pl.playerId;}));};
 if($('clear-map-filter'))$('clear-map-filter').onclick=()=>{filter.region='all';render();};
 if($('place-marker'))$('place-marker').onclick=()=>{mapState.placing=!mapState.placing;$('place-marker').setAttribute('aria-pressed',String(mapState.placing));$('place-marker').textContent=mapState.placing?'點圖選位置中；再次按此取消':'在示意圖選個人位置';if(mapState.placing)$('yard-map').focus();};
 if($('marker-form'))$('marker-form').onsubmit=e=>{e.preventDefault();const marker={name:$('marker-name').value.trim(),note:$('marker-note').value,x:Number($('marker-x').value),y:Number($('marker-y').value),layer:$('marker-layer').value,done:false};if(!marker.name)return;void action(()=>update(p=>{run(p).customMarkers[crypto.randomUUID()]={...marker,...stampActor(p),positionAccuracy:'personal'};}));};
 if($('ng-backup'))$('ng-backup').onclick=()=>void action(async()=>{const raw=await store.stamp();download(JSON.parse(raw),'before-ng');ngBackupStamp=raw;message('下載已發起；請開啟檔案確認保存，再建立周目。');});
 if($('ng-ack'))$('ng-ack').onchange=()=>{$('ng-create').disabled=!$('ng-ack').checked||!ngBackupStamp;};
 if($('ng-create'))$('ng-create').onclick=()=>void action(async()=>{if(!$('ng-ack').checked||!ngBackupStamp)throw Error('請先備份並確認');await store.checkpoint('新增 NG+ 前');await store.update(p=>{addRun(p);return p;},ngBackupStamp);ngBackupStamp=null;message('新周目已建立；第一輪原始記錄保留。');});
 for(const [id,key]of [['ng-molar-count','count'],['ng-molar-status','status']])if($(id))$(id).onchange=e=>{const value=key==='count'?Number(e.target.value):e.target.value;void action(()=>update(p=>{if(key==='count'&&(!Number.isSafeInteger(value)||value<0||value>999))throw Error('請輸入 0–999 的整數');run(p).ngMolars[key]=value;}));};
}
function resetCollectionFilters(){Object.assign(filter,{search:'',category:'all',region:'all',status:'all',verification:'all',required:'all',layer:'all'});}
function download(data,label){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='game-companion.grounded.'+label+'.'+Date.now()+'.json';document.body.append(a);try{a.click();}finally{a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}}
async function preview(file){if(file.size>20*1024*1024)throw Error('匯入檔超過 20 MB，已停止；原始檔保留');const sourceRaw=await file.text(),localRaw=await store.stamp();await store.archive({sourceRaw,localRaw,at:Date.now(),label:'匯入兩端原文'});const source=importData(JSON.parse(sourceRaw)),local=JSON.parse(localRaw),plan=core.merge(null,local,source,{hasBase:false});review={plan,bundle:{sourceRaw,localRaw,at:Date.now()},stamp:localRaw,choices:plan.conflicts.map(()=>''),downloaded:false,invalid:false};$('import-ack').checked=false;$('import-ack').disabled=true;$('import-status').textContent=plan.conflicts.length+' 筆差異；兩端原文已保存在本遊戲復原區。';renderReview();$('backup-dialog').close();$('import-dialog').showModal();}
function renderReview(){$('import-rows').innerHTML=review.plan.conflicts.map((c,i)=>`<div class="diff"><strong>${escape(c.path.join(' / '))}</strong><div class="diff-values"><pre>本機\n${escape(JSON.stringify(c.local,null,2)??'未記錄')}</pre><pre>來源\n${escape(JSON.stringify(c.remote,null,2)??'未記錄')}</pre></div><select data-diff="${i}" aria-label="匯入差異 ${i+1}">${options([['','請選擇'],['local','本機'],['remote','來源']],review.choices[i])}</select></div>`).join('')||'<p>沒有進度差異；仍須下載兩端原文復原包並確認。</p>';$('import-rows').querySelectorAll('[data-diff]').forEach(s=>s.onchange=()=>{review.choices[Number(s.dataset.diff)]=s.value;importReady();});importReady();}
function importReady(){$('import-apply').disabled=!review||review.invalid||!review.downloaded||!$('import-ack').checked||review.choices.some(c=>!c);}
$('open-backup').onclick=()=>$('backup-dialog').showModal();
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());
$('export-progress').onclick=()=>void action(async()=>download(await store.raw(),'progress'));
$('export-recovery').onclick=()=>void action(async()=>download(await store.exportAll(),'recovery'));
$('import-file').onchange=e=>{const file=e.target.files[0];e.target.value='';if(file)void action(()=>preview(file));};
for(const [id,choice]of [['import-local','local'],['import-source','remote']])$(id).onclick=()=>{review.choices.fill(choice);renderReview();};
$('import-download').onclick=()=>void action(async()=>{try{if(await store.stamp()!==review.stamp)throw Error('預覽已過期，請重新比較');download({recoveryBundle:review.bundle},'before-import');review.downloaded=true;$('import-ack').disabled=false;$('import-status').textContent='下載已發起；請開啟檔案確認已保存，瀏覽器不能保證落盤。';}catch(e){review.downloaded=false;$('import-ack').disabled=true;$('import-status').textContent='備份失敗：'+e.message;}importReady();});
$('import-ack').onchange=importReady;
$('import-apply').onclick=()=>void action(async()=>{if($('import-apply').disabled)return;try{const next=store.validate(core.resolve(review.plan,review.choices)).data;await store.checkpoint('匯入前');await store.update(()=>next,review.stamp);$('import-dialog').close();review=null;message('匯入完成；兩端原文與未知資料已保留。');}catch(e){review.invalid=true;$('import-status').textContent=e.message;importReady();}});
document.querySelectorAll('[data-view]').forEach(a=>a.onclick=e=>{e.preventDefault();filter.search='';go(a.dataset.view);$('handbook-nav').classList.remove('open');$('nav-toggle').setAttribute('aria-expanded','false');});
$('nav-toggle').onclick=()=>{const open=$('handbook-nav').classList.toggle('open');$('nav-toggle').setAttribute('aria-expanded',String(open));};
window.addEventListener('popstate',()=>{filter.stage=new URL(location.href).searchParams.get('stage')||filter.stage;render();});
window.addEventListener('pagehide',()=>store.close(),{once:true});
$('app').tabIndex=-1;
try{progress=await store.open();filter.stage=new URL(location.href).searchParams.get('stage')||run(progress).storyStage||'start';render();}catch(e){$('app').innerHTML=`<h1>進度無法讀取</h1><p class="error">${escape(e.message)}</p><p>原始資料未被空進度覆蓋。可使用右上角完整復原備份保存原文。</p>`;}
